"""增量更新 GKI 内核版本数据。"""import copyimport jsonimport osimport sysimport timefrom gki_fetch import (    TARGETS,    fetch_lts,    fetch_latest_release_tags,    fetch_makefile,    fetch_monthly_branches,    fetch_tag_makefile,    get_end_date,    json_path,    make_date_range,    parse_version,)from prepare_matrix import validate_datadef update_target(android_ver: str, kernel_ver: str,                  date_start: str, date_end: str | None,                  dep_cutoff: str) -> bool:    path = json_path(android_ver, kernel_ver)    end = get_end_date(date_end)    has_release_tags = kernel_ver in ("5.10", "5.15")    if os.path.exists(path):        with open(path, "r", encoding="utf-8") as f:            data = json.load(f)        entries = data.get("entries", [])        legacy_lts = next((e for e in entries if e.get("date") == "lts"), None)        if legacy_lts is not None:            if data.get("lts") not in (None, legacy_lts.get("kernel")):                raise ValueError(f"conflicting LTS values in {path}")            data["lts"] = legacy_lts.get("kernel")            entries = [e for e in entries if e.get("date") != "lts"]            data["entries"] = entries        validate_data(data, path, android_ver, kernel_ver)    else:        data = {            "android_version": android_ver,            "kernel_version": kernel_ver,            "lts": None,            "entries": [],        }        entries = []    original_data = copy.deepcopy(data)    pinned_dates = data.get("pinned_dates") if has_release_tags else None    if pinned_dates is not None:        pinned_dates = set(pinned_dates)        entries = [            entry for entry in entries            if entry.get("date") in pinned_dates        ]        data["entries"] = entries    existing_by_date = {e["date"]: e for e in entries}    all_dates = make_date_range(date_start, end)    if has_release_tags:        fixed_months = (            pinned_dates if pinned_dates is not None            else {date for date in existing_by_date if date != "lts"}        )        if fixed_months:            print("  固定的月度版本保持不变，仅更新 LTS")        else:            # Empty pinned_dates means this target tracks all monthly releases.            # Persist that mode so future runs continue to discover new months.            if pinned_dates is None:                data["pinned_dates"] = []            release_tags = fetch_latest_release_tags(android_ver, kernel_ver)            monthly_branches = fetch_monthly_branches(android_ver, kernel_ver)            for date in all_dates:                current = existing_by_date.get(date)                previous = current.copy() if current is not None else None                release = release_tags.get(date)                tag = release[0] if release is not None else None                if tag is None:                    if date not in monthly_branches:                        if current is not None:                            raise RuntimeError(f"no release tag or branch for {android_ver}-{kernel_ver}-{date}")                        continue                    text = fetch_makefile(android_ver, kernel_ver, date, dep_cutoff)                    if text is None:                        if date == end and current is None:                            print(f"  [{date}] monthly branch has no Makefile yet, skip")                            continue                        raise RuntimeError(f"monthly branch has no Makefile: {android_ver}-{kernel_ver}-{date}")                else:                    text = fetch_tag_makefile(*release)                ver = parse_version(text)                if ver is None:                    raise RuntimeError(f"failed to parse Makefile for {tag or date}")                detail = ".".join(ver)                if current is None:                    current = {"date": date, "kernel": detail}                    entries.append(current)                    existing_by_date[date] = current                else:                    current["kernel"] = detail                if tag is not None:                    current["revision"] = "r" + tag.rsplit("_r", 1)[1]                else:                    current.pop("revision", None)                if current != previous:                    print(f"  [{tag or date}] -> {detail}")                time.sleep(0.3)    else:        new_dates = [date for date in all_dates if date not in existing_by_date]        if not new_dates:            print("  No new months to fetch")        monthly_branches = (            fetch_monthly_branches(android_ver, kernel_ver) if new_dates else set()        )        for date in new_dates:            label = f"{android_ver}-{kernel_ver}-{date}"            print(f"    [{label}] ", end="", flush=True)            if date not in monthly_branches:                print("not found, skip")                continue            text = fetch_makefile(android_ver, kernel_ver, date, dep_cutoff)            if text is None:                print("not found, skip")                continue            ver = parse_version(text)            if ver is None:                raise RuntimeError(f"failed to parse Makefile for {label}")            detail = ".".join(ver)            entries.append({"date": date, "kernel": detail})            print(f"-> {detail}")            time.sleep(0.3)    # 按月份排序    entries.sort(key=lambda e: e.get("date", ""))    # 更新 LTS    lts_label = f"{android_ver}-{kernel_ver}-lts"    print(f"  [{lts_label}] ", end="", flush=True)    lts_text = fetch_lts(android_ver, kernel_ver)    if lts_text is None:        raise RuntimeError(f"LTS branch not found: {lts_label}")    ver = parse_version(lts_text)    if ver is None:        raise RuntimeError(f"failed to parse Makefile for {lts_label}")    version, patchlevel, sublevel = ver    lts_value = f"{version}.{patchlevel}.{sublevel}"    old_lts = data.get("lts")    if old_lts != lts_value:        data["lts"] = lts_value        print(f"-> {lts_value} (was {old_lts})")    else:        print(f"-> {lts_value} (unchanged)")    data["entries"] = entries    validate_data(data, path, android_ver, kernel_ver)    changed = data != original_data    if changed:        os.makedirs(os.path.dirname(path), exist_ok=True)        temp_path = f"{path}.tmp"        with open(temp_path, "w", encoding="utf-8") as f:            json.dump(data, f, indent=2, ensure_ascii=False)            f.write("\n")        os.replace(temp_path, path)        print(f"  => Saved {len(entries)} entries to {path}")    else:        print(f"  => No changes")    return changeddef main():    any_changed = False    for (android_ver, kernel_ver), (date_start, date_end, dep_cutoff) in TARGETS.items():        print(f"\n=== {android_ver} / {kernel_ver} ===")        if update_target(android_ver, kernel_ver, date_start, date_end, dep_cutoff):            any_changed = True    print(f"\n{'Data updated.' if any_changed else 'All data up-to-date.'}")    return any_changedif __name__ == "__main__":    try:        main()    except Exception as e:        print(f"\nFATAL: {e}", file=sys.stderr)        sys.exit(1)    sys.exit(0)